'use strict';
const fleetBadgeFits=new Map();
let fleetRenderedKey=null;
function aircraftBadge(name){
 const entry=resolveAircraft(name);
 if(!entry){const placeholder=document.createElement('span');placeholder.className='fleet-placeholder';const symbol=document.createElement('span');symbol.textContent='✈';symbol.setAttribute('aria-hidden','true');const model=document.createElement('strong');model.textContent=name;const label=document.createElement('span');label.textContent='暂无徽章';placeholder.append(symbol,model,label);return {node:placeholder,description:'暂无徽章'};}
 const img=document.createElement('img');img.src=entry.badge;fitFleetBadge(img);img.alt='';img.loading='lazy';img.decoding='async';img.width=640;img.height=640;
 return {node:img,description:'机型艺术徽章'};
}
const fleetPage=document.createElement('section');fleetPage.className='fleet-page';fleetPage.hidden=true;fleetPage.innerHTML='<div class="fleet-heading"><div><h2>我的机型收藏册</h2><p id="fleet-count"></p></div></div><p id="fleet-missing"></p><div class="fleet-sections" id="fleet-grid"></div>';document.querySelector('main').append(fleetPage);
const fleetNav=document.createElement('button');fleetNav.type='button';fleetNav.dataset.view='fleet';fleetNav.textContent='机型收藏册';document.querySelector('.view-links').append(fleetNav);
const fleetDialog=document.createElement('dialog');fleetDialog.className='flight-dialog';fleetDialog.innerHTML='<div class="dialog-heading"><h2 id="fleet-detail-title"></h2><button type="button" class="dialog-close" id="fleet-close" aria-label="关闭">×</button></div><div id="fleet-detail"></div>';document.body.append(fleetDialog);$('fleet-close').onclick=()=>fleetDialog.close();
function fleetKey(value){return String(value||'').trim().replace(/\s+/g,' ');}
function fleetGroups(){const groups=new Map();let missing=0;for(const r of state.rows||[]){const date=dateValue(r.date);if(!date||date>localDate()||recordCanceled(r)||recordNeedsCorrection(r))continue;const name=fleetKey(r.aircraft);if(!name){missing++;continue;}const key=aircraftIdentity(name);if(!groups.has(key))groups.set(key,{name,rows:[]});groups.get(key).rows.push(r);}return {groups:[...groups.values()].sort((a,b)=>b.rows.length-a.rows.length||a.name.localeCompare(b.name)),missing};}
function fleetDetail(g){$('fleet-detail-title').textContent=g.name;const box=$('fleet-detail');box.replaceChildren();for(const r of [...g.rows].sort(compareFlightDeparture)){const row=document.createElement('div');row.className='fleet-leg';const title=document.createElement('strong');title.textContent=`${recordAirportName(r.from)} → ${recordAirportName(r.to)}`;const sub=document.createElement('span');sub.textContent=`${dateValue(r.date)} · ${normalizeAirlineCode(r.airline)} ${r.flight||''} · ${airportCode(r.from)} → ${airportCode(r.to)}`;row.append(title,sub);box.append(row);}fleetDialog.showModal();}
function fleetMaker(name){const maker=resolveAircraft(name)?.manufacturer;if(maker)return maker==='Boeing'?'波音':maker==='Airbus'?'空客':'其他';const n=String(name).toUpperCase();if(/BOEING|^B?7[0-9]{2}(?:\b|[- ])/.test(n))return '波音';if(/AIRBUS|^A3[0-9]{2}/.test(n))return '空客';return '其他';}
function fleetCollection(groups){const catalog=new Map(aircraftCatalog.map(({id,name})=>[id,{name,rows:[]}]));const extra=[];for(const group of groups){const entry=ribbonEntry(group.name);if(entry)catalog.get(entry[0]).rows.push(...group.rows);else extra.push(group);}return [...catalog.values(),...extra];}
function renderFleet(){const key=localDate()+'|'+editorReady+'|'+JSON.stringify(state.rows||[]);if(key===fleetRenderedKey)return;const {groups:flown,missing}=fleetGroups(),groups=fleetCollection(flown);const collected=groups.filter(g=>g.rows.length);$('fleet-count').textContent=`已解锁 ${collected.filter(g=>resolveAircraft(g.name)).length} 枚徽章 · 已记录 ${collected.length} 种机型 · ${groups.reduce((n,g)=>n+g.rows.length,0)} 次飞行`;$('fleet-missing').textContent=missing?`${missing} 条历史行程尚未填写机型，可在航班记录中补齐。`:'';const box=$('fleet-grid');box.replaceChildren();const sections=new Map(),order=['波音','空客','其他'];const visible=groups.slice().sort((a,b)=>order.indexOf(fleetMaker(a.name))-order.indexOf(fleetMaker(b.name))||b.rows.length-a.rows.length||a.name.localeCompare(b.name));for(const g of visible){const maker=fleetMaker(g.name);if(!sections.has(maker)){const section=document.createElement('section');section.className='fleet-section';const heading=document.createElement('h3');heading.className='fleet-section-title';heading.textContent=maker;const grid=document.createElement('div');grid.className='fleet-grid';section.append(heading,grid);box.append(section);sections.set(maker,grid);}const button=document.createElement('button');button.type='button';button.className='fleet-card'+(g.rows.length?'':' is-locked');button.disabled=!g.rows.length;const art=aircraftBadge(g.name);const icon=document.createElement('div');icon.className='fleet-icon';icon.append(art.node);button.title=g.name+' · '+art.description+'（示意图）';button.setAttribute('aria-label',g.name+(g.rows.length?'，'+g.rows.length+' 次飞行，查看航班记录':'，未解锁'));const title=document.createElement('h3');title.textContent=g.name;title.className='fleet-name-a11y';const detail=document.createElement('p');const airlines=new Set(g.rows.map(r=>normalizeAirlineCode(r.airline)).filter(Boolean)),routes=new Set(g.rows.map(r=>[airportCode(r.from),airportCode(r.to)].join('→')));detail.textContent=g.rows.length?`${g.rows.length} 次飞行`:'未解锁';button.title+=` · ${airlines.size} 家航司 · ${routes.size} 条单向航线`;const dates=g.rows.map(r=>dateValue(r.date)).sort();const first=document.createElement('small');first.textContent=dates.length?`首乘 ${dates[0]}`:'\u00a0';button.append(icon,title,detail,first);button.onclick=()=>fleetDetail(g);sections.get(maker).append(button);}if(!box.children.length){const empty=document.createElement('p');empty.textContent=groups.length?'没有匹配的机型。':'添加已飞行且填写了机型的航班，开启你的收藏册。';box.append(empty);}fleetRenderedKey=key;}
const originalShowWorkspace=showWorkspace;showWorkspace=function(view){originalShowWorkspace(view==='fleet'?'records':view);fleetPage.hidden=view!=='fleet';if(view==='fleet'){records.hidden=true;workspace.hidden=true;$('workspace-title').textContent='每一种飞机，一段新的记忆。';$('workspace-description').textContent='从历史行程中收集你乘坐过的机型。';document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view==='fleet')b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});renderFleet();}};
fleetNav.onclick=()=>showWorkspace('fleet');const updateVisibleFleet=()=>{if(!fleetPage.hidden)renderFleet();};window.addEventListener('atlas:rows',updateVisibleFleet);window.addEventListener('atlas:airports-ready',updateVisibleFleet);

dismissOnBackdrop(fleetDialog);

if(typeof renderRecords==='function')renderRecords();

function fitFleetBadge(img){
 const key=img.src;if(fleetBadgeFits.has(key)){img.style.transform=fleetBadgeFits.get(key);return;}
 img.addEventListener('load',()=>{try{
  if(fleetBadgeFits.has(key)){img.style.transform=fleetBadgeFits.get(key);return;}
  const canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
  const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(img,0,0);
  const pixels=context.getImageData(0,0,canvas.width,canvas.height).data;
  let left=canvas.width,top=canvas.height,right=-1,bottom=-1;
  for(let y=0;y<canvas.height;y++)for(let x=0;x<canvas.width;x++)if(pixels[(y*canvas.width+x)*4+3]>32){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}
  if(right<left){fleetBadgeFits.set(key,'');return;}
  const edge=Math.max(canvas.width,canvas.height),scale=.96*edge/Math.max(right-left+1,bottom-top+1);
  img.style.transform='translate('+((canvas.width/2-(left+right+1)/2)/edge*scale*100)+'%, '+((canvas.height/2-(top+bottom+1)/2)/edge*scale*100)+'%) scale('+scale+')';
  fleetBadgeFits.set(key,img.style.transform);
 }catch{/* Keep the original image if pixel inspection is unavailable. */}},{once:true});
}
